<script setup lang="ts">
import { onBeforeUnmount, ref } from 'vue';
import { Download, FileText, Upload } from 'lucide-vue-next';
import { ElMessage } from 'element-plus';
import { api } from '../api';
import { binary, fail, safetyDownload } from '../safety-workspace';
import { saveBlob } from '../admission';
const props=withDefaults(defineProps<{modelValue?:any[];enterpriseId?:string;editable?:boolean;videoOnly?:boolean;endpoint?:string}>(),{modelValue:()=>[],endpoint:'/safety/workspace/materials'});
const emit=defineEmits<{'update:modelValue':[files:any[]];busy:[value:boolean]}>();
const input=ref<HTMLInputElement>(),uploading=ref(false),error=ref(''),preview=ref(false),previewFile=ref<any>(),previewUrl=ref(''),previewLoading=ref(false),previewError=ref('');let generation=0;
async function upload(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;if(input.value)input.value.value='';if(!props.enterpriseId)return ElMessage.warning('请先选择所属企业或车辆');if(props.modelValue.length>=20)return ElMessage.warning('最多关联20份材料');uploading.value=true;error.value='';emit('busy',true);try{const body=new FormData();body.set('file',file);body.set('enterpriseId',props.enterpriseId);const material=await api<any>(props.endpoint,{method:'POST',body});if(props.videoOnly&&material.mimeType!=='video/mp4')throw new Error('请选择MP4录像');emit('update:modelValue',[...props.modelValue,material]);}catch(e){error.value=fail(e)}finally{uploading.value=false;emit('busy',false)}}
async function open(file:any){preview.value=true;previewFile.value=file;await loadPreview()}
async function loadPreview(){const current=++generation;if(previewUrl.value)URL.revokeObjectURL(previewUrl.value);previewUrl.value='';previewLoading.value=true;previewError.value='';try{const blob=await binary(`${props.endpoint}/${previewFile.value.id}/content`);if(current===generation)previewUrl.value=URL.createObjectURL(blob)}catch(e){if(current===generation)previewError.value=fail(e)}finally{if(current===generation)previewLoading.value=false}}
async function download(file:any){try{if(props.endpoint==='/safety/workspace/materials')await safetyDownload(file);else saveBlob(await binary(`${props.endpoint}/${file.id}/content`),file.name);}catch(e){ElMessage.error(fail(e))}}
function closed(){generation++;if(previewUrl.value)URL.revokeObjectURL(previewUrl.value);previewUrl.value=''}onBeforeUnmount(closed);
</script>
<template><div class="safety-materials"><div v-for="(file,index) in modelValue" :key="file.id" class="safety-file"><FileText :size="17"/><button type="button" @click="open(file)">{{file.name}}</button><small>{{(file.size/1024/1024).toFixed(1)}}MB</small><el-button link type="primary" :icon="Download" :aria-label="`下载${file.name}`" @click="download(file)"/><el-button v-if="editable" link type="danger" :disabled="uploading" @click="emit('update:modelValue',modelValue.filter((_,i)=>i!==index))">移除</el-button></div><span v-if="!modelValue.length&&!editable" class="safety-muted">尚未提交材料</span><template v-if="editable"><input ref="input" class="sr-only" type="file" :accept="videoOnly?'.mp4':'.pdf,.png,.jpg,.jpeg,.mp4'" aria-label="选择安全监管材料" @change="upload"/><el-button :icon="Upload" :loading="uploading" :disabled="!enterpriseId" @click="input?.click()">{{videoOnly?'上传MP4录像':'上传材料'}}</el-button><small class="safety-muted">{{videoOnly?'MP4':'PDF、PNG、JPG、MP4'}}，单份不超过100MB</small></template><p v-if="error" role="alert" class="safety-error-text">{{error}}</p><el-dialog v-model="preview" :title="previewFile?.name||'材料预览'" width="min(1000px,95vw)" append-to-body destroy-on-close @closed="closed"><div v-loading="previewLoading" class="safety-preview"><div v-if="previewError" class="safety-error"><p>{{previewError}}</p><el-button @click="loadPreview">重新读取</el-button></div><template v-else-if="previewUrl"><img v-if="previewFile?.mimeType?.startsWith('image/')" :src="previewUrl" :alt="previewFile.name"/><video v-else-if="previewFile?.mimeType==='video/mp4'" :src="previewUrl" controls/><iframe v-else :src="previewUrl" :title="previewFile?.name"/></template></div></el-dialog></div></template>
